package com.example.lab4.domain; import jakarta.persistence.*; import java.util.UUID; @Entity public class SupportRequest { @Id UUID id; @ManyToOne Customer customer; String subject; String priority; String status; protected SupportRequest(){} public UUID getId(){return id;} public String getPriority(){return priority;} public String getStatus(){return status;} public void setStatus(String s){status=s;} }
